let currentLang = localStorage.getItem('luxe_lang') || 'fr';
if (!I18N[currentLang]) currentLang = 'fr';

function t(path) {
  const parts = path.split('.');
  let node = I18N[currentLang], fallback = I18N.fr;
  for (const p of parts) { node = node && node[p]; fallback = fallback && fallback[p]; }
  return node !== undefined ? node : fallback;
}

function setLang(lang) {
  if (!I18N[lang]) return;
  currentLang = lang;
  localStorage.setItem('luxe_lang', lang);
  document.documentElement.lang = lang;
  if (typeof renderApp === 'function') renderApp();
}
